REM Run by run.sh in this directory, which also creates APP_OWNER through the container APP_USER variable.
set echo on
set serveroutput on
whenever sqlerror continue
SELECT BANNER_FULL FROM V$VERSION;
CREATE USER APP_RO IDENTIFIED BY "not-a-real-password";
GRANT CREATE SESSION TO APP_RO;
ALTER USER APP_RO READ ONLY;
CREATE TABLE APP_OWNER.T1 (ID NUMBER PRIMARY KEY, NAME VARCHAR2(40), DOC CLOB, BIN BLOB);
INSERT INTO APP_OWNER.T1 VALUES (1, 'one', 'clob one', HEXTORAW('DEADBEEF'));
INSERT INTO APP_OWNER.T1 VALUES (2, 'two', 'clob two', NULL);
COMMIT;
CREATE TABLE APP_OWNER.LOGT (MSG VARCHAR2(100));
GRANT SELECT ON APP_OWNER.T1 TO APP_RO;
GRANT SELECT ON APP_OWNER.LOGT TO APP_RO;
CREATE OR REPLACE FUNCTION APP_OWNER.WRITE_AUTON RETURN NUMBER AS
  PRAGMA AUTONOMOUS_TRANSACTION;
BEGIN
  INSERT INTO APP_OWNER.LOGT VALUES ('autonomous ' || USER);
  COMMIT;
  RETURN 1;
END;
/
GRANT EXECUTE ON APP_OWNER.WRITE_AUTON TO APP_RO;
SELECT READ_ONLY FROM DBA_USERS WHERE USERNAME IN ('APP_RO','APP_OWNER');
SELECT GRANTEE, TABLE_NAME, PRIVILEGE FROM DBA_TAB_PRIVS WHERE GRANTEE='PUBLIC' AND TABLE_NAME IN ('UTL_HTTP','UTL_TCP','UTL_SMTP','UTL_FILE','DBMS_SCHEDULER','DBMS_PIPE','UTL_INADDR','DBMS_LDAP','DBMS_JAVA','UTL_MAIL','DBMS_SQL','DBMS_LOB','DBMS_XSLPROCESSOR','DBMS_ADVISOR','DBMS_AQ','HTTPURITYPE','DBMS_NETWORK_ACL_ADMIN','DBMS_CLOUD');
SELECT COUNT(*) FROM DBA_DB_LINKS;
SELECT DIRECTORY_NAME FROM DBA_DIRECTORIES;

set feedback on
CREATE TABLE APP_OWNER.SCRATCH (ID NUMBER);
GRANT SELECT, INSERT, UPDATE, DELETE ON APP_OWNER.SCRATCH TO APP_RO;

set feedback on
CREATE SEQUENCE APP_OWNER.SEQ1;
GRANT SELECT ON APP_OWNER.SEQ1 TO APP_RO;
CREATE USER APP_RO_SYS IDENTIFIED BY "not-a-real-password";
GRANT CREATE SESSION, ALTER SYSTEM, ALTER SESSION TO APP_RO_SYS;
ALTER USER APP_RO_SYS READ ONLY;
CREATE ROLE RO_ROLE;
GRANT SELECT ON APP_OWNER.SCRATCH TO RO_ROLE;
GRANT RO_ROLE TO APP_RO;
ALTER USER APP_RO DEFAULT ROLE NONE;
CREATE PUBLIC DATABASE LINK LOOPLINK CONNECT TO APP_OWNER IDENTIFIED BY "not-a-real-password" USING 'localhost:1521/FREEPDB1';
CREATE SEQUENCE APP_OWNER.SEQ2;
CREATE OR REPLACE FUNCTION APP_OWNER.NEXT_ID RETURN NUMBER AS BEGIN RETURN APP_OWNER.SEQ2.NEXTVAL; END;
/
GRANT EXECUTE ON APP_OWNER.NEXT_ID TO APP_RO;
GRANT ALTER SYSTEM TO APP_OWNER;
CREATE OR REPLACE FUNCTION APP_OWNER.BUMP RETURN NUMBER AS BEGIN EXECUTE IMMEDIATE 'ALTER SYSTEM SET OPEN_CURSORS = 333'; RETURN 1; END;
/
GRANT EXECUTE ON APP_OWNER.BUMP TO APP_RO;
